func Render(s store.Store) (map[string][]byte, error) {
	tickets, err := s.Tickets()
	if err != nil {
		return nil, err
	}
	out := map[string][]byte{"WORK.md": WorkMD(tickets)}

	for _, t := range tickets {
		if t.NotesPreamble == "" && len(t.NoteEntries) == 0 {
